import path from "node:path";
import { describe, expect, it } from "vitest";

import { collectBaselineUnstructuredRelativePaths } from "../collectBaselineUnstructuredPaths";

describe("collectBaselineUnstructuredRelativePaths", () => {
	const datasetRoot = path.resolve(__dirname, "../../../../testfiles");

	it("collects all .eml under emails/ and .pdf under rechnungen/ (not HistoryPopulationData)", () => {
		const paths = collectBaselineUnstructuredRelativePaths(datasetRoot);

		expect(paths.length).toBe(6546 + 194);
		expect(paths.every((p) => !p.includes("HistoryPopulationData"))).toBe(true);
		expect(new Set(paths).size).toBe(paths.length);
		expect(paths.some((p) => p.startsWith("emails/2024-") && p.endsWith(".eml"))).toBe(
			true,
		);
		expect(paths.some((p) => p.startsWith("rechnungen/2024-") && p.endsWith(".pdf"))).toBe(
			true,
		);
		expect(paths.filter((p) => p.endsWith(".eml")).length).toBe(6546);
		expect(paths.filter((p) => p.endsWith(".pdf")).length).toBe(194);
	});

	it("returns POSIX-style relative paths sorted for stable ordering", () => {
		const paths = collectBaselineUnstructuredRelativePaths(datasetRoot);
		expect(paths[0] < paths[paths.length - 1]).toBe(true);
		expect(paths.every((p) => !path.isAbsolute(p))).toBe(true);
		expect(paths.every((p) => !p.includes("\\"))).toBe(true);
	});
});

import { readdirSync, statSync } from "node:fs";
import path from "node:path";

const BASELINE_UNSTRUCTURED_ROOTS = ["emails", "rechnungen"] as const;

function walkFilesRecursive(absoluteDir: string, datasetRoot: string, acc: string[]): void {
	for (const ent of readdirSync(absoluteDir, { withFileTypes: true })) {
		const full = path.join(absoluteDir, ent.name);
		if (ent.isDirectory()) {
			walkFilesRecursive(full, datasetRoot, acc);
		} else if (ent.isFile()) {
			const rel = path.relative(datasetRoot, full);
			const posixRel = rel.split(path.sep).join("/");
			if (posixRel.includes("HistoryPopulationData")) {
				continue;
			}
			if (posixRel.endsWith(".eml") || posixRel.endsWith(".pdf")) {
				acc.push(posixRel);
			}
		}
	}
}

/**
 * Lists unstructured baseline inputs: all `.eml` under `emails/` and `.pdf` under `rechnungen/`
 * relative to the dataset root, excluding anything under `HistoryPopulationData` (replay corpus).
 */
export function collectBaselineUnstructuredRelativePaths(datasetRootAbsolute: string): string[] {
	const resolvedRoot = path.resolve(datasetRootAbsolute);
	if (!statSync(resolvedRoot, { throwIfNoEntry: false })?.isDirectory()) {
		return [];
	}

	const acc: string[] = [];
	for (const root of BASELINE_UNSTRUCTURED_ROOTS) {
		const dir = path.join(resolvedRoot, root);
		if (statSync(dir, { throwIfNoEntry: false })?.isDirectory()) {
			walkFilesRecursive(dir, resolvedRoot, acc);
		}
	}

	return acc.sort((a, b) => a.localeCompare(b));
}

import { readFile } from "node:fs/promises";

export type ErpUnitRow = {
	hausId: string;
	einheitNr: string;
};

export type ErpStammdatenContext = {
	unitToHaus: Map<string, ErpUnitRow>;
	hausIdToDisplayName: Map<string, string>;
};

type StammdatenJson = {
	einheiten?: Array<{ id: string; haus_id: string; einheit_nr: string }>;
	gebaeude?: Array<{ id: string; hausnr: string }>;
};

export async function loadErpStammdatenContextFromFile(
	absolutePath: string,
): Promise<ErpStammdatenContext | null> {
	try {
		const raw = await readFile(absolutePath, "utf-8");
		const data = JSON.parse(raw) as StammdatenJson;
		const unitToHaus = new Map<string, ErpUnitRow>();
		for (const einheit of data.einheiten ?? []) {
			if (einheit?.id && einheit?.haus_id) {
				unitToHaus.set(einheit.id, {
					hausId: einheit.haus_id,
					einheitNr: einheit.einheit_nr ?? einheit.id,
				});
			}
		}
		const hausIdToDisplayName = new Map<string, string>();
		for (const g of data.gebaeude ?? []) {
			if (g?.id) {
				hausIdToDisplayName.set(g.id, g.hausnr ? `Haus ${g.hausnr}` : g.id);
			}
		}
		return { unitToHaus, hausIdToDisplayName };
	} catch {
		return null;
	}
}

